const priceCharts=[];const priceMap=new Map(priceCharts.map(x=>[x.id,x]));const steelSeasonColors={2021:'#7030a0',2022:'#5b9bd5',2023:'#a5a5a5',2024:'#ffc000',2025:'#000000',2026:'#ff0000'};
function priceDay(d){return (Date.parse('2024-'+d.slice(5))-Date.parse('2024-01-01'))/86400000/366}
function tightPriceAxis(values){
 if(!values.length)return {lo:0,hi:1,tick:.2};
 let min=Math.min(...values),max=Math.max(...values);
 if(min===max){let t=10**Math.floor(Math.log10(Math.abs(min)||1))/10;return {lo:min-t,hi:max+t,tick:t};}
 const rough=(max-min)/5,base=10**Math.floor(Math.log10(rough));
 const tick=[1,2,2.5,5,10].map(x=>x*base).find(x=>x>=rough);
 let lo=Math.floor((min+tick*1e-10)/tick)*tick,hi=Math.ceil((max-tick*1e-10)/tick)*tick;
 if(hi<=lo)hi=lo+tick;
 return {lo,hi,tick};
}
function drawPrice(canvas,hover){
 const r=canvas.getBoundingClientRect();if(!r.width||r.bottom<0||r.top>innerHeight+500)return;
 const data=priceMap.get(canvas.dataset.priceChart);if(!data)return;const hidden=data.hidden||(data.hidden=new Set());const years=[2021,2022,2023,2024,2025,2026,...(data.extraYears||[])].filter(y=>data.series.some(p=>(p.seasonYear??+p.date.slice(0,4))===y));
 const ps=data.series.filter(p=>p.value!==null&&Number.isFinite(p.value)&&years.includes(p.seasonYear??+p.date.slice(0,4))&&!hidden.has(p.seasonYear??+p.date.slice(0,4)));let w=r.width,h=300,dpr=devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.font='12px "Times New Roman",KaiTi';
 const vals=ps.map(p=>p.value);if(Number.isFinite(data.referenceValue))vals.push(data.referenceValue);let lo=Math.min(...vals),hi=Math.max(...vals);if(!vals.length){lo=0;hi=1}let pad=Math.max((hi-lo)*.12,1);lo-=pad;hi+=pad;let step=10**Math.floor(Math.log10((hi-lo)/4)),tick=[1,2,5,10].map(x=>x*step).find(x=>x>=(hi-lo)/4);lo=Math.floor(lo/tick)*tick;hi=Math.ceil(hi/tick)*tick;const scoped=canvas.closest('[data-directory-number]')?.dataset.directoryNumber?.split('.')[0]==='3';if(scoped){({lo,hi,tick}=tightPriceAxis(vals));}data.axisRange={lo,hi,tick,min:vals.length?Math.min(...vals):null,max:vals.length?Math.max(...vals):null,scoped};const L=52,R=w-12,T=28,B=h-30;const chartDay=d=>priceDay(data.monthly?d.slice(0,7)+"-01":d);const pointDay=p=>data.lunar?(p.cnyOffset+181)/383:chartDay(p.date);const XP=p=>L+pointDay(p)*(R-L);const X=d=>L+chartDay(d)*(R-L),Y=v=>B-(v-lo)/(hi-lo)*(B-T);ctx.clearRect(0,0,w,h);
 for(let v=lo;v<=hi+tick*.01;v+=tick){ctx.strokeStyle='#e1e6ed';ctx.beginPath();ctx.moveTo(L,Y(v));ctx.lineTo(R,Y(v));ctx.stroke();ctx.fillStyle='#344054';ctx.fillText(v.toFixed(Math.min(8,Math.max(0,Math.ceil(-Math.log10(tick)))+(Math.abs(tick/10**Math.floor(Math.log10(tick))-2.5)<1e-8?1:0))),2,Y(v)+4)}
 if(data.lunar){[-168,-112,-56,0,56,112,168].forEach(v=>{ctx.fillStyle='#344054';ctx.fillText(v===0?'春节':'W'+(v>0?'+':'')+v/7,L+(v+181)/383*(R-L)-12,h-9)})}else for(let m=1;m<=12;m++){ctx.fillStyle='#344054';ctx.fillText(m+'/1',X('2024-'+String(m).padStart(2,'0')+'-01')-8,h-9)}
 if(Number.isFinite(data.referenceValue)){ctx.save();ctx.strokeStyle='#87919e';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(L,Y(data.referenceValue));ctx.lineTo(R,Y(data.referenceValue));ctx.stroke();ctx.restore();}data.legend=[];years.forEach((y,i)=>{const x=w/2-years.length*27+i*54;ctx.globalAlpha=hidden.has(y)?.3:1;ctx.fillStyle=(steelSeasonColors[y]||'#374151');ctx.fillRect(x,5,12,3);ctx.fillText(y,x+16,11);ctx.globalAlpha=1;data.legend.push({year:y,left:x,right:x+49});if(hidden.has(y))return;const pts=data.series.filter(p=>(p.seasonYear??+p.date.slice(0,4))===y);ctx.strokeStyle=(steelSeasonColors[y]||'#374151');ctx.lineWidth=y===2026?2.4:1.3;ctx.setLineDash(y>2026?[4,3]:[]);ctx.beginPath();let previous=null;pts.forEach(p=>{if(p.value===null||!Number.isFinite(p.value)){return}const gap=previous?(Date.parse(p.date)-Date.parse(previous.date))/86400000:Infinity;if(previous)ctx.lineTo(XP(p),Y(p.value));else ctx.moveTo(XP(p),Y(p.value));previous=p});if(data.extraYears?.includes(y)&&pts.length===1&&Number.isFinite(pts[0].value)){ctx.moveTo(X(pts[0].date)-3,Y(pts[0].value));ctx.lineTo(X(pts[0].date)+3,Y(pts[0].value))}ctx.stroke();ctx.setLineDash([])});
 if(hover!=null){const x=Math.max(L,Math.min(R,hover)),target=(x-L)/(R-L);ctx.strokeStyle='#667085';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,T);ctx.lineTo(x,B);ctx.stroke();const tip=canvas.nextElementSibling;tip.style.display='block';tip.innerHTML=years.filter(y=>!hidden.has(y)).map(y=>{const pts=data.series.filter(p=>(p.seasonYear??+p.date.slice(0,4))===y);const p=pts.reduce((best,p)=>Math.abs(pointDay(p)-target)<Math.abs(pointDay(best)-target)?p:best,pts[0]);return p?'<div style="color:'+(steelSeasonColors[y]||'#374151')+'">'+p.date+'：'+(p.value==null?'#N/A':p.value.toFixed(2)+' '+data.unit)+'</div>':''}).join('')}
 data.rendered=true;
}
const priceObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)drawPrice(e.target)}),{rootMargin:'300px'});
document.querySelectorAll('[data-price-chart]').forEach(canvas=>{priceObserver.observe(canvas);canvas.onpointermove=e=>drawPrice(canvas,e.clientX-canvas.getBoundingClientRect().left);canvas.onpointerleave=()=>{canvas.nextElementSibling.style.display='none';drawPrice(canvas)};canvas.onclick=e=>{const r=canvas.getBoundingClientRect();if(e.clientY-r.top>21)return;const d=priceMap.get(canvas.dataset.priceChart);const item=d?.legend?.find(x=>e.clientX-r.left>=x.left&&e.clientX-r.left<=x.right);if(item){d.hidden.has(item.year)?d.hidden.delete(item.year):d.hidden.add(item.year);drawPrice(canvas)}}});
let priceFrame;function refreshPrices(){cancelAnimationFrame(priceFrame);priceFrame=requestAnimationFrame(()=>document.querySelectorAll('[data-price-chart]').forEach(c=>drawPrice(c)))}window.addEventListener('resize',refreshPrices);window.addEventListener('scroll',refreshPrices,{passive:true});new ResizeObserver(refreshPrices).observe(document.body);refreshPrices();
window.steelPriceDataReady=(async()=>{const bytes=Uint8Array.from(atob(""),c=>c.charCodeAt(0));const rows=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text());for(const row of rows){priceCharts.push(row);priceMap.set(row.id,row)}refreshPrices();return priceCharts.length;})();